    }    else if (value is Cve98260StageEvent) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is Cve98260Chunk) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is KernelProfile) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is KernelProfileImportResult) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is KernelProfileFieldValue) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is KernelProfileEditorState) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is RunLogBeginRequest) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is RunLogFinishRequest) {
      buffer.putUint8(139);
